#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3); RED=$(tput setaf 1)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""; RED=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1; then tput clear; else printf '\033[2J\033[3J\033[H'; fi
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else warn "couldn't open a browser; visit it manually: $url"; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  printf '%s' "${line#*=}"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret).
ask() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -r input || true
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || true
  printf '\n'
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY=VALUE into ENV_FILE (creates it; replaces
# any existing line). Idempotent.
write_env() {
  local key="$1" value="$2" tmp
  touch "$ENV_FILE"
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf '%s=%s\n' "$key" "$value" >> "$tmp"
  mv "$tmp" "$ENV_FILE"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# ──────────────────────────────────────────────────────────────────────────

TOTAL_STAGES=4
set +x
umask 077
if [[ "$#" != 0 ]]; then printf 'Usage: ./dev setup\n' >&2; exit 2; fi
root=$(cd -- "$(dirname -- "${BASH_SOURCE[0]}")/../.." && pwd)
helper="$root/scripts/dev/cli.mjs"
command -v node >/dev/null || { printf 'Install Node from apps/reef/.node-version first.\n' >&2; exit 1; }
printf 'Checking prerequisites and existing configuration...\n'
TAILNET_HOST=$(node "$helper" _prepare)
ENV_FILE="$root/.dev/setup.env"
if ! mkdir "$root/.dev/setup.lock" 2>/dev/null; then
  printf 'Another setup is running, or .dev/setup.lock remains from an interrupted setup. Check before removing it.\n' >&2
  exit 1
fi
trap 'rmdir "$root/.dev/setup.lock" 2>/dev/null || true' EXIT

capture() {
  local name="$1" prompt="$2"
  ask "$name" "$prompt"
  printf '%s' "${!name}" | node "$helper" _validate "$name"
  write_env "$name" "${!name}"
}

banner "Coral development setup"
say "Installing Reef dependencies and building Coral before collecting credentials..."
node "$helper" _install

stage "Confirm the machine and WorkOS environment"
say "This checkout gets its own .dev/ configuration, database, and signing keys."
say "Tailscale hostname: $TAILNET_HOST"
confirm "Use this machine for your development stack?" || exit 1
write_env TAILNET_HOST "$TAILNET_HOST"
open_url "https://dashboard.workos.com"
step "Select the WorkOS environment to develop against, and enter its values below."
say "Your team keeps these values in its password manager. Enter keeps a saved value."
capture WORKOS_ISSUER "AuthKit HTTPS issuer (no trailing slash):"
step "Developer / API Keys contains the environment client ID, not the Connect application ID."
capture WORKOS_ENVIRONMENT_CLIENT_ID "Environment client ID:"
capture WORKOS_ORGANIZATION_ID "WorkOS Organization ID to admit:"

stage "Create your development Connect application"
open_url "https://dashboard.workos.com"
step "In Connect, create a separate OAuth application for your development machine."
step "Choose Managed by you and confidential/client-secret authentication, not public/PKCE-only."
step "Give it a recognizable name, for example Coral dev plus your name."
node "$helper" _urls
step "Register the WorkOS Connect callback printed above as the application's redirect URI."
confirm "Is that exact callback registered on your Connect application?" || exit 1
capture WORKOS_CONNECT_CLIENT_ID "Connect OAuth client ID:"
note "Use the Connect client secret, NOT a WorkOS API key. Input is hidden and stored only in .dev/."
ask_secret WORKOS_CONNECT_CLIENT_SECRET "Connect client secret:"
printf '%s' "$WORKOS_CONNECT_CLIENT_SECRET" | node "$helper" _validate WORKOS_CONNECT_CLIENT_SECRET
write_env WORKOS_CONNECT_CLIENT_SECRET "$WORKOS_CONNECT_CLIENT_SECRET"
unset WORKOS_CONNECT_CLIENT_SECRET

stage "Select your initial Coral Organization Owner"
open_url "https://dashboard.workos.com"
step "Find your own account under Users and confirm membership in the selected Organization."
step "Copy its user_... User ID, not an email or a membership ID."
capture WORKOS_OWNER_SUB "Initial Owner's WorkOS User ID:"
confirm "Should this exact account be the initial Owner of this checkout's Coral installation?" || exit 1
note "WorkOS's signed identity and Organization are checked at login. Coral owns the resulting roles."
note "Google sign-in is configured once per WorkOS environment. See docs/development.md if Google reports redirect_uri_mismatch."

stage "Generate private configuration and configure HTTPS"
node "$helper" _urls
say "Local ports: Reef 5173; Coral gRPC 14555; auth 9080; MCP 14556."
say "Tailscale HTTPS: 443 → auth and MCP (split by path), 8443 → Reef."
note "New mappings use private Serve; matching existing Serve/Funnel mappings keep their visibility."
note "Mappings from the earlier per-port layout (443 Reef, 8443 auth, 10000 MCP) are replaced with private Serve."
warn "Existing Funnel mappings remain public. Reef's Vite server exposes development source."
note "Existing unrelated .env files, data directories, and conflicting mappings are never replaced."
confirm "Generate this checkout's configuration and configure those HTTPS mappings?" || exit 1
node "$helper" _configure
if confirm "Use sudo for the Tailscale Serve commands?"; then
  node "$helper" proxy --sudo
else
  node "$helper" proxy
fi
finish
say "Run ./dev run for combined terminal output, ./dev run --herdr in a fresh Herdr shell, or ./dev run --rex in a fresh Rex tab."
say "You can also run ./dev coral and ./dev reef in two ordinary terminals."
say "The runner checks readiness and prints the web URL. Use ./dev doctor to check an already-running stack."
note "No service is installed. Ctrl-C stops the processes started by that command."
